import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long a = scanner.nextLong();
        long b = scanner.nextLong();
        long n = scanner.nextLong();
        long minDifference = 1000000000L;
        long bestX = 0;
        long bestY = 0;
        for (long y = 1; y <= n; y++) {
            long xCandidate = (a * y) / b;
            for (int offset = -5; offset <= 5; offset++) {
                long currentX = xCandidate + offset;
                long currentDiff = Math.abs(b * currentX - a * y);
                if (currentDiff * 1000000000L < minDifference * b * y) {
                    minDifference = currentDiff;
                    bestX = currentX;
                    bestY = y;
                }
            }
        }
        System.out.println(bestX + "/" + bestY);
        scanner.close();
    }
}
